from __future__ import absolute_import, division, print_function,\
    unicode_literals
from future import standard_library
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
logger = BackgroundLogger.Instance()
standard_library.install_aliases()


class TEIDNotGeneratedException(Exception):
    """
        Exception for TEID Not generated error
    """
    pass


class BandChangeFailedException(Exception):
    """
        Exception for Band change error
    """
    pass


class PingFailedException(Exception):
    """
        Exception for Ping fail error
    """
    pass


class VoiceCallException(Exception):
    """
        Exception for Voice call not happening error
    """
    pass


class AdbDeviceNotDetected(Exception):
    pass


class IpNotFoundException(Exception):
    pass


class VoiceCallError(Exception):
    pass


class AttachMessagesNotFound(Exception):
    pass


class ProfileNotPassedException(Exception):
    pass


class DeviceInUseException(Exception):
    pass


class AttachFailed(Exception):
    pass


class AdbExecutionError(Exception):
    """
      An error while executing adb command
    """
    def __init__(self, msg=None):
        if not msg:
            msg = "An error while executing adb command"
        logger.error(msg)


